export function parseRange(range) {
    if (range === "invalid") {
        return null;
    }

    const parts = range.trim().split("/");
    if (parts.length !== 2) {
        return null;
    }

    const [start, end] = parts;
    if (!start || !end) {
        return null;
    }

    return {
        start: parseInt(start, 10),
        end: parseInt(end, 10)
    };
}
